function hit(x,y){for(let i=polys.length-1;i>=0;i--){const {points:p,id}=polys[i];let inside=false;for(let a=0,b=p.length-1;a<p.length;b=a++)if((p[a].y>y)!==(p[b].y>y)&&x<(p[b].x-p[a].x)*(y-p[a].y)/(p[b].y-p[a].y)+p[a].x)inside=!inside;if(inside)return id;}return null;}
