 if(kind==='rail'){const rail=layout.rails.find(r=>onDeck(r,deck)),a=layout.rooms.find(r=>r.id===rail.a),b=layout.rooms.find(r=>r.id===rail.b),px=from.x+from.w/2;target=Math.abs(px-a.x)<Math.abs(px-b.x)?b:a;}else{const next=(deck+1)%layout.config.decks,candidates=layout.rooms.filter(r=>r.deck===next&&r.type==='station'),px=from.x+from.w/2;target=[candidates[0],candidates.at(-1)].sort((a,b)=>Math.abs(a.x-px)-Math.abs(b.x-px))[0];}
