canvas.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(mode==='compare'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','[',']'].includes(e.key)){e.preventDefault();if(e.key==='['||e.key===']')comparison.rotate(e.key==='['?-5:5);else comparison.pan(e.key==='ArrowLeft'?-12:e.key==='ArrowRight'?12:0,e.key==='ArrowUp'?-12:e.key==='ArrowDown'?12:0);return;}if(mode==='compare'&&(key==='e'||key==='r'||key==='enter'))return;if(key==='e'||key==='r'){e.preventDefault();travel(key==='e'?'elevator':'rail');return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','=','Enter'].includes(e.key)){e.preventDefault();if(e.key==='Enter'){const list=layout.rooms.filter(r=>onDeck(r,deck)&&r.type!=='transit'),i=list.findIndex(r=>r.id===selected);selected=list[(i+1)%list.length]?.id;inspect();}else if(e.key==='ArrowLeft')yaw-=.12;else if(e.key==='ArrowRight')yaw+=.12;else if(e.key==='ArrowUp')pitch=Math.min(1.45,pitch+.1);else if(e.key==='ArrowDown')pitch=Math.max(.15,pitch-.1);else zoom=Math.max(.08,Math.min(8,zoom*(e.key==='-'?.9:1.1)));draw();}});
